/**
 * HeatShield AI - Client-Side All-India Administrative Hierarchy Store & Universal Resolver
 * Contains all 36 States/UTs, all 787 official districts of India, and sub-districts/villages.
 * Supports universal fuzzy search, hierarchical drilldown, offline persistence, and IDW evaluation.
 */

import { interpolateLocationFeaturesOffline } from './offlineEngine';
import type { LocationPredictionResponse } from '../types';

export interface StateGeoRecord {
  state_code: string;
  state_name: string;
  type: 'State' | 'UT';
  capital: string;
  latitude: number;
  longitude: number;
  district_count: number;
  climate_zone: string;
}

export interface DistrictGeoRecord {
  district_id: string;
  district_name: string;
  state_code: string;
  state_name: string;
  latitude: number;
  longitude: number;
  headquarters: string;
  elevation_m: number;
  climate_zone: string;
  tehsils: string[];
  sample_villages: string[];
}

export interface VillageGeoRecord {
  name: string;
  type: 'village' | 'tehsil' | 'district' | 'state';
  state_name: string;
  state_code: string;
  district_name: string;
  tehsil_name?: string;
  latitude: number;
  longitude: number;
  climate_zone: string;
  display_label: string;
  hierarchy: string;
  is_custom?: boolean;
}

